using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;
namespace CyberPW.Assistant2{internal sealed class CyberButton:Button{public int CornerRadius=10;public int BorderThickness=3;bool hover;public CyberButton(){FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;SetStyle(ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.UserPaint,true);MouseEnter+=(s,e)=>{hover=true;Invalidate();};MouseLeave+=(s,e)=>{hover=false;Invalidate();};}protected override void OnResize(System.EventArgs e){base.OnResize(e);if(Width>0&&Height>0){using(var p=Path(new Rectangle(0,0,Width,Height),CornerRadius)){var old=Region;Region=new Region(p);if(old!=null)old.Dispose();}}}protected override void OnPaint(PaintEventArgs e){e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;Rectangle r=new Rectangle(2,2,Math.Max(1,Width-5),Math.Max(1,Height-5));using(var path=Path(r,CornerRadius)){Color fill=!Enabled?Color.FromArgb(45,55,52):(hover?Color.FromArgb(18,104,82):BackColor);using(var brush=new SolidBrush(fill))e.Graphics.FillPath(brush,path);using(var pen=new Pen(FlatAppearance.BorderColor.IsEmpty?Theme.Gold:FlatAppearance.BorderColor,BorderThickness))e.Graphics.DrawPath(pen,path);}Rectangle textRect=new Rectangle(Padding.Left,0,Width-Padding.Horizontal,Height);if(Image!=null){int x=Padding.Left+4,y=(Height-Image.Height)/2;e.Graphics.DrawImage(Image,x,y,Image.Width,Image.Height);textRect.X=x+Image.Width+7;textRect.Width=Width-textRect.X-Padding.Right;}TextFormatFlags flags=TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis;if(TextAlign==ContentAlignment.MiddleLeft)flags|=TextFormatFlags.Left;else if(TextAlign==ContentAlignment.MiddleRight)flags|=TextFormatFlags.Right;else flags|=TextFormatFlags.HorizontalCenter;TextRenderer.DrawText(e.Graphics,Text,Font,textRect,Enabled?ForeColor:Color.Gray,flags);}static GraphicsPath Path(Rectangle r,int radius){var p=new GraphicsPath();int d=Math.Min(radius*2,Math.Min(r.Width,r.Height));p.AddArc(r.Left,r.Top,d,d,180,90);p.AddArc(r.Right-d,r.Top,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.Left,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}}
